INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'ta'), 'A1', 'greetings', 'Greetings', 'Greet your neighbours and introduce yourself in Tamil.', 'You''ve just moved into a rented flat in Mylapore. Saroja amma, the house owner, comes to say hello.', '“Vanakkam” works with everyone. Add “-nga” to be polite: “irukeenga”, “sollunga”. Even “Tamil konjam konjam theriyum” (I know a little Tamil) gets a smile.', 1, 'published', datetime('now'), datetime('now'), 1);
