INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'ta'), 'A1', 'transport', 'Transport', 'Take autos, MTC buses and the Chennai Metro, and agree the fare.', 'You need to get from Chennai Central to T. Nagar in the evening rush.', 'Autos are meant to use the meter, but most Chennai drivers quote a fixed fare: agree on it before you sit in, or book through an app. MTC buses and the Metro are cheap, and women travel free on MTC''s ordinary buses.', 2, 'published', datetime('now'), datetime('now'), 1);
