INSERT INTO lessons(language_id, cefr_code, slug, title, description, situation, tip, sort_order, status, published_at, updated_at, revision) VALUES ((SELECT id FROM languages WHERE code = 'ta'), 'A1', 'shopping', 'Shopping', 'Ask prices, sizes and pay, and bargain where it''s normal.', 'You''re on Ranganathan Street in T. Nagar looking for a kurta.', 'Bargain on Ranganathan Street and in Pondy Bazaar, never in malls or shops with price tags. Numbers: onnu, rendu, moonu, naalu, anju, aaru, ezhu, ettu, onbadhu, patthu; nooru (100), aayiram (1000).', 4, 'published', datetime('now'), datetime('now'), 1);
