INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'ta'), 'A1', 'polite-requests', 1);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ta') AND slug = 'polite-requests'), (SELECT id FROM languages WHERE code = 'en'), 'Polite requests: “-unga”', 'Tamil asks politely with the “neenga” (you, polite) form of the verb, which ends in -unga: “kudunga” (please give), “podunga” (please put), “sollunga” (please say), “pannunga” (please do). With friends the short form is used: “kudu”, “podu”, “sollu”.');
