INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'ta'), 'A1', 'yes-no-questions', 2);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ta') AND slug = 'yes-no-questions'), (SELECT id FROM languages WHERE code = 'en'), 'Yes-no questions: “-aa”', 'Add -aa to ask a yes-no question: “irukku” (there is) becomes “irukkaa?” (is there?), “pogum” (it goes) becomes “pogumaa?” (does it go?), “dhooram” (far) becomes “dhooramaa?” (is it far?).');
