INSERT INTO grammar_topics(language_id, cefr_code, slug, sort_order) VALUES ((SELECT id FROM languages WHERE code = 'ta'), 'A1', 'to-a-place', 3);
INSERT INTO grammar_topic_texts(grammar_topic_id, language_id, title, explanation) VALUES ((SELECT id FROM grammar_topics WHERE language_id = (SELECT id FROM languages WHERE code = 'ta') AND slug = 'to-a-place'), (SELECT id FROM languages WHERE code = 'en'), 'Going to a place: “-kku” and “-ukku”', 'Tamil puts “to” at the end of the place: “-kku” after a vowel (Chennaikku) and “-ukku” after a consonant (Adyarukku). With “pogumaa?” (will it go?) the place is often said on its own: “T. Nagar pogumaa?”.');
